$page = 1;
$all = [];
while (true) {
    $res = $tools->call('publishing_list', ['page' => $page]);
    foreach ($res->items as $item) {
        $all[] = $item;
    }
    if ($res->nextPage === null) {
        break;
    }
    $page = $res->nextPage;
}
$audited = count($all);
$missing = [];
foreach ($all as $it) {
    if (trim($it->meta_description) === '') {
        $missing[] = $it->id;
    }
}
sort($missing);
return ['audited' => $audited, 'missing' => $missing];

