$article = $tools->call('publishing_read', ['id' => 1]);
// Ensure we have the fields
$id = $article->id;
$title = $article->title;
$body = $article->body;
// Create a short summary: first sentence or first 150 chars.
$summary = '';
if (preg_match('/^.*?[.!?](\s|$)/', $body, $m)) {
    $summary = trim($m[0]);
} else {
    $summary = substr($body, 0, 150);
    $summary = trim($summary);
    if (strlen($body) > 150) $summary .= '...';
}
return ['id' => $id, 'title' => $title, 'summary' => $summary];

$page = 1;
$total = 0;
$missing = [];
while (true) {
    $result = $tools->call('publishing_list', ['page' => $page]);
    foreach ($result->items as $item) {
        $total++;
        $desc = $item->meta_description;
        if (trim($desc) === '') {
            $missing[] = $item->id;
        }
    }
    if ($result->nextPage === null) {
        break;
    }
    $page = $result->nextPage;
}
sort($missing, SORT_NUMERIC);
return ['audited' => $total, 'missing' => $missing];

